      "label": "1",
      "angle": "从使用体验与支撑结构切入，再讲打理与携带",
      "blocks": [
        {
          "stage": "welcome",
          "focus": "开场问候",
          "sentences": [
            {
              "display_text": "欢迎来到直播间，今天咱们来看一款很顺手的小本子。",
              "spoken_text": "欢迎来到直播间，今天咱们来看一款很顺手的小本子。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "你有没有那种时刻，想随手记点东西，手边却没合适的纸？",
              "spoken_text": "你有没有那种时刻，想随手记点东西，手边却没合适的纸？",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "pain",
          "focus": "日常记录缺纸的困扰",
          "sentences": [
            {
              "display_text": "比如开会时突然要做笔记，翻开手机备忘录又觉得戳屏幕不够快。",
              "spoken_text": "比如开会时突然要做笔记，翻开手机备忘录又觉得戳屏幕不够快。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "或者坐在桌前想理一理今天要做的事，写下来比在脑子里转更清楚。",
              "spoken_text": "或者坐在桌前想理一理今天要做的事，写下来比在脑子里转更清楚。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "这种时候，如果手边有一本大小合适、翻开就能写的本子，节奏就顺很多。",
              "spoken_text": "这种时候，如果手边有一本大小合适、翻开就能写的本子，节奏就顺很多。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        },
        {
          "stage": "identity",
          "focus": "商品身份与核心用途",
          "sentences": [
            {
              "display_text": "今天介绍的是轻记A5点阵笔记本。",
              "spoken_text": "今天介绍的是轻记A5点阵笔记本。",
              "kind": "product_claim",
              "fact_ids": ["NAME"]
            },
            {
              "display_text": "它内页是点阵格式，日常记录、简单手账、学习笔记都可以用。",
              "spoken_text": "它内页是点阵格式，日常记录、简单手账、学习笔记都可以用。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "点阵内页的使用体验",
          "sentences": [
            {
              "display_text": "点阵内页和横线本不一样，它没有一条条横线框住你。",
              "spoken_text": "点阵内页和横线本不一样，它没有一条条横线框住你。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "你想写整齐的笔记，就顺着点来对齐；想画个小图或拉个表格，也比纯白纸更容易找位置。",
              "spoken_text": "你想写整齐的笔记，就顺着点来对齐；想画个小图或拉个表格，也比纯白纸更容易找位置。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "这种自由度很适合那些写笔记时偶尔想配个小示意、写手账时想贴点小记录的人。",
              "spoken_text": "这种自由度很适合那些写笔记时偶尔想配个小示意、写手账时想贴点小记录的人。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "A5尺寸与80页的容量",
          "sentences": [
            {
              "display_text": "它是A5大小，放在桌面上不占太多地方，拿在手里也稳当。",
              "spoken_text": "它是A5大小，放在桌面上不占太多地方，拿在手里也稳当。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "80页的容量，用来写一段时间的日常记录或者一门课的笔记，心里有个底。",
              "spoken_text": "80页的容量，用来写一段时间的日常记录或者一门课的笔记，心里有个底。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "去图书馆或者咖啡店，包里塞一本，想写的时候翻开就用。",
              "spoken_text": "去图书馆或者咖啡店，包里塞一本，想写的时候翻开就用。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "软封面带来的携带手感",
          "sentences": [
            {
              "display_text": "封面是软面的，拿在手里不会硬邦邦的。",
              "spoken_text": "封面是软面的，拿在手里不会硬邦邦的。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "平时从桌上拿起来翻，或者卷一下塞进帆布袋侧袋，都比较随和。",
              "spoken_text": "平时从桌上拿起来翻，或者卷一下塞进帆布袋侧袋，都比较随和。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "放在床头或者办公桌角落，软封面也不容易显得太正式，随手翻开压力小。",
              "spoken_text": "放在床头或者办公桌角落，软封面也不容易显得太正式，随手翻开压力小。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "specification",
          "focus": "颜色选择与搭配建议",
          "sentences": [
            {
              "display_text": "封面颜色有浅灰和浅绿两种。",
              "spoken_text": "封面颜色有浅灰和浅绿两种。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "浅灰比较低调，放在办公桌上或者带出门都不太挑环境。",
              "spoken_text": "浅灰比较低调，放在办公桌上或者带出门都不太挑环境。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "浅绿多了一点清亮的感觉，写给自己的日常记录或者手账，看着心情也轻快些。",
              "spoken_text": "浅绿多了一点清亮的感觉，写给自己的日常记录或者手账，看着心情也轻快些。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "你可以根据平时用本子的场合来选，两个颜色都只有这一种规格，不用纠结型号。",
              "spoken_text": "你可以根据平时用本子的场合来选，两个颜色都只有这一种规格，不用纠结型号。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "price",
          "focus": "价格与优惠条件",
          "sentences": [
            {
              "display_text": "这本轻记A5点阵笔记本售价是19元。",
              "spoken_text": "这本轻记A5点阵笔记本售价是十九元。",
              "kind": "product_claim",
              "fact_ids": ["PRICE"]
            },
            {
              "display_text": "没有另外的活动价，页面价格就是十九元。",
              "spoken_text": "没有另外的活动价，页面价格就是十九元。",
              "kind": "product_claim",
              "fact_ids": ["PRICE"]
            },
            {
              "display_text": "另外有一项优惠：购买3本可以享9折，不与其他优惠叠加。",
              "spoken_text": "另外有一项优惠：购买三本可以享九折，不与其他优惠叠加。",
              "kind": "product_claim",
              "fact_ids": ["PROMOTION"]
            },
            {
              "display_text": "活动截止时间资料里没有提供，以页面显示为准。",
              "spoken_text": "活动截止时间资料里没有提供，以页面显示为准。",
              "kind": "product_claim",
              "fact_ids": ["PROMOTION"]
            }
          ]
        },
        {
          "stage": "cta",
          "focus": "自然购买引导",
          "sentences": [
            {
              "display_text": "如果你正好缺一本随手写写画画的小本子，可以按照喜欢的颜色来选。",
              "spoken_text": "如果你正好缺一本随手写写画画的小本子，可以按照喜欢的颜色来选。",
              "kind": "engagement",
              "fact_ids": []
            },
            {
              "display_text": "买三本享九折这个条件，适合想给自己备一本、再送朋友一本的情况。",
              "spoken_text": "买三本享九折这个条件，适合想给自己备一本、再送朋友一本的情况。",
              "kind": "product_claim",
              "fact_ids": ["PROMOTION"]
            },
            {
              "display_text": "合适再下单，不着急也没关系。",
              "spoken_text": "合适再下单，不着急也没关系。",
              "kind": "engagement",
              "fact_ids": []
            }
          ]
        }
      ]
    }
